:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --highlight: #e94560;
  --border: #533483;
  --focus: #f9c74f;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg);
  background-image: 
    linear-gradient(45deg, var(--accent) 25%, transparent 25%),
    linear-gradient(-45deg, var(--accent) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, var(--accent) 75%),
    linear-gradient(-45deg, transparent 75%, var(--accent) 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.6;
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 2rem 1rem;
}

.faq-card {
  background-color: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--accent);
  padding: 2rem;
  max-width: 800px;
  width: 100%;
  image-rendering: pixelated;
}

h1 {
  font-size: 2rem;
  color: var(--highlight);
  text-align: center;
  margin-bottom: 1.5rem;
  text-shadow: 2px 2px 0 var(--accent);
  letter-spacing: 2px;
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.control-btn {
  font-family: var(--font);
  font-size: 1rem;
  padding: 0.75rem 1.5rem;
  background-color: var(--accent);
  color: var(--text);
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 var(--border);
  cursor: pointer;
  transition: all 0.1s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.control-btn:hover {
  background-color: var(--highlight);
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--border);
}

.control-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--border);
}

.control-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.faq-item {
  border: 2px solid var(--border);
  background-color: var(--bg);
}

.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  padding: 1rem 1.25rem;
  font-family: var(--font);
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--text);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: background-color 0.2s;
  gap: 1rem;
}

.faq-question:hover {
  background-color: var(--accent);
}

.faq-question:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: -3px;
}

.faq-question .arrow {
  display: inline-block;
  width: 1.5rem;
  height: 1.5rem;
  flex-shrink: 0;
  transition: transform 0.3s ease;
  font-size: 1.2rem;
  line-height: 1.5rem;
  text-align: center;
  color: var(--highlight);
}

.faq-question[aria-expanded="true"] .arrow {
  transform: rotate(90deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  padding: 0 1.25rem;
  background-color: var(--card-bg);
  border-top: 2px solid transparent;
}

.faq-answer.open {
  max-height: 500px;
  padding: 1rem 1.25rem;
  border-top-color: var(--border);
}

.faq-answer p {
  margin: 0;
}

@media (max-width: 480px) {
  body {
    font-size: 16px;
    padding: 1rem 0.5rem;
  }
  .faq-card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .control-btn {
    font-size: 0.9rem;
    padding: 0.6rem 1rem;
  }
  .faq-question {
    font-size: 1rem;
    padding: 0.75rem 1rem;
  }
  .faq-answer.open {
    padding: 0.75rem 1rem;
  }
}

const faqData = [
  {
    question: "What is a pixel?",
    answer: "A pixel is the smallest controllable element of a picture represented on a screen. The word is short for 'picture element'."
  },
  {
    question: "Why use pixel art?",
    answer: "Pixel art is a form of digital art where images are created at the individual pixel level. It has a distinct retro aesthetic and is often used in indie games."
  },
  {
    question: "How do I create pixel art?",
    answer: "You can use software like Aseprite, GraphicsGale, or even simple tools like Piskel. Start with a small canvas (e.g., 32x32) and zoom in."
  },
  {
    question: "What are common pixel art palettes?",
    answer: "Popular palettes include PICO-8, Game Boy (4 shades of green), and NES. Limiting your palette helps maintain a cohesive look."
  },
  {
    question: "Can pixel art be animated?",
    answer: "Yes! Pixel art animation is common in games. You create multiple frames and cycle through them quickly, just like traditional animation."
  }
];

document.addEventListener('DOMContentLoaded', () => {
  const faqList = document.getElementById('faq-list');
  const expandAllBtn = document.getElementById('expand-all');
  const collapseAllBtn = document.getElementById('collapse-all');

  // Build FAQ items
  faqData.forEach((item, index) => {
    const faqItem = document.createElement('div');
    faqItem.className = 'faq-item';

    const questionBtn = document.createElement('button');
    questionBtn.className = 'faq-question';
    questionBtn.setAttribute('aria-expanded', 'false');
    questionBtn.setAttribute('aria-controls', `answer-${index}`);
    questionBtn.id = `question-${index}`;

    const arrow = document.createElement('span');
    arrow.className = 'arrow';
    arrow.setAttribute('aria-hidden', 'true');
    arrow.textContent = '▶';

    const questionText = document.createElement('span');
    questionText.textContent = item.question;

    questionBtn.appendChild(questionText);
    questionBtn.appendChild(arrow);

    const answerDiv = document.createElement('div');
    answerDiv.className = 'faq-answer';
    answerDiv.id = `answer-${index}`;
    answerDiv.setAttribute('role', 'region');
    answerDiv.setAttribute('aria-labelledby', `question-${index}`);

    const answerP = document.createElement('p');
    answerP.textContent = item.answer;
    answerDiv.appendChild(answerP);

    faqItem.appendChild(questionBtn);
    faqItem.appendChild(answerDiv);
    faqList.appendChild(faqItem);

    questionBtn.addEventListener('click', () => {
      const isOpen = questionBtn.getAttribute('aria-expanded') === 'true';
      closeAll();
      if (!isOpen) {
        openItem(questionBtn, answerDiv);
      }
    });
  });

  function closeAll() {
    document.querySelectorAll('.faq-question').forEach(btn => {
      btn.setAttribute('aria-expanded', 'false');
      const answer = document.getElementById(btn.getAttribute('aria-controls'));
      if (answer) answer.classList.remove('open');
    });
  }

  function openItem(btn, answer) {
    btn.setAttribute('aria-expanded', 'true');
    answer.classList.add('open');
  }

  expandAllBtn.addEventListener('click', () => {
    document.querySelectorAll('.faq-question').forEach(btn => {
      btn.setAttribute('aria-expanded', 'true');
      const answer = document.getElementById(btn.getAttribute('aria-controls'));
      if (answer) answer.classList.add('open');
    });
  });

  collapseAllBtn.addEventListener('click', closeAll);
});
